/**
 * Anti-Detection Utilities
 * 
 * Implementa técnicas para tornar o comportamento do bot menos detectável,
 * sem impactar significativamente a velocidade de envio.
 * 
 * @module anti-detection
 * @version 1.0.0
 */

/**
 * Gerador de variação natural de timing
 * 
 * Usa distribuição gaussiana (normal) ao invés de uniforme
 * para criar padrões mais naturais e menos detectáveis.
 */
export class NaturalTimingGenerator {
    /**
     * Gera delay com distribuição gaussiana
     * 
     * @param {number} mean - Valor médio (ms)
     * @param {number} stdDev - Desvio padrão (ms)
     * @param {number} min - Valor mínimo (ms)
     * @param {number} max - Valor máximo (ms)
     * @returns {number} Delay em ms
     */
    static gaussian(mean, stdDev, min = 0, max = Infinity) {
        // Box-Muller transform para distribuição normal
        const u1 = Math.random();
        const u2 = Math.random();
        const z0 = Math.sqrt(-2.0 * Math.log(u1)) * Math.cos(2.0 * Math.PI * u2);
        
        const value = mean + z0 * stdDev;
        return Math.max(min, Math.min(max, Math.round(value)));
    }
    
    /**
     * Gera delay com variação natural
     * 
     * @param {number} min - Mínimo (ms)
     * @param {number} max - Máximo (ms)
     * @returns {number} Delay em ms
     */
    static natural(min, max) {
        const mean = (min + max) / 2;
        const stdDev = (max - min) / 6; // 99.7% entre min e max
        return this.gaussian(mean, stdDev, min, max);
    }
}

/**
 * Gerenciador de padrões de presença
 * 
 * Varia o comportamento de presença para parecer mais humano.
 */
export class PresencePatternManager {
    constructor() {
        this.lastPresenceTime = new Map();
        this.presenceProbability = 0.9; // 90% chance de enviar presença
        this.pausedProbability = 0.8; // 80% chance de enviar "paused"
    }
    
    /**
     * Decide se deve enviar presença
     * 
     * @param {string} jid - JID do destinatário
     * @returns {boolean} Se deve enviar presença
     */
    shouldSendPresence(jid) {
        // Evita enviar presença muito frequentemente para o mesmo JID
        const lastTime = this.lastPresenceTime.get(jid);
        if (lastTime && Date.now() - lastTime < 5000) { // 5 segundos
            return false;
        }
        
        return Math.random() < this.presenceProbability;
    }
    
    /**
     * Decide se deve enviar "paused"
     * 
     * @returns {boolean} Se deve enviar "paused"
     */
    shouldSendPaused() {
        return Math.random() < this.pausedProbability;
    }
    
    /**
     * Calcula tempo de digitação natural
     * 
     * @param {number} messageLength - Tamanho da mensagem
     * @returns {number} Tempo em ms
     */
    calculateTypingTime(messageLength) {
        // Velocidade de digitação humana: 20-50ms por caractere
        const charsPerMs = 20 + Math.random() * 30;
        const baseTime = messageLength * charsPerMs;
        
        // Adiciona pausas aleatórias (simula "pensar")
        const pauseTime = Math.random() * 800;
        
        // Limita a 4 segundos (mensagens muito longas)
        return Math.min(baseTime + pauseTime, 4000);
    }
    
    /**
     * Registra envio de presença
     * 
     * @param {string} jid - JID do destinatário
     */
    recordPresence(jid) {
        this.lastPresenceTime.set(jid, Date.now());
    }
}

/**
 * Gerenciador de padrões de atividade
 * 
 * Rastreia atividade para evitar padrões muito regulares.
 */
export class ActivityPatternManager {
    constructor() {
        this.messagesSent = 0;
        this.lastMessageTime = 0;
        this.hourlyStats = new Map(); // hora -> contagem
    }
    
    /**
     * Registra envio de mensagem
     */
    recordMessage() {
        this.messagesSent++;
        this.lastMessageTime = Date.now();
        
        const hour = new Date().getHours();
        const count = this.hourlyStats.get(hour) || 0;
        this.hourlyStats.set(hour, count + 1);
    }
    
    /**
     * Obtém estatísticas de atividade
     * 
     * @returns {object} Estatísticas
     */
    getStats() {
        return {
            totalMessages: this.messagesSent,
            lastMessageTime: this.lastMessageTime,
            hourlyDistribution: Object.fromEntries(this.hourlyStats)
        };
    }
    
    /**
     * Verifica se está em horário de pico
     * 
     * @returns {boolean} Se está em horário de pico
     */
    isPeakHour() {
        const hour = new Date().getHours();
        // Horários de pico: 9-12h e 14-18h
        return (hour >= 9 && hour <= 12) || (hour >= 14 && hour <= 18);
    }
    
    /**
     * Limpa estatísticas antigas (executar diariamente)
     */
    resetDaily() {
        this.hourlyStats.clear();
    }
}

/**
 * Factory para criar gerenciadores anti-detecção
 */
export function createAntiDetectionManagers() {
    return {
        timing: new NaturalTimingGenerator(),
        presence: new PresencePatternManager(),
        activity: new ActivityPatternManager()
    };
}

export default {
    NaturalTimingGenerator,
    PresencePatternManager,
    ActivityPatternManager,
    createAntiDetectionManagers
};
